from fastapi import Depends, FastAPI
from pydantic import BaseModel

app = FastAPI()

class TicketIn(BaseModel):
    title: str
    priority: int

def get_current_user():
    return {'id': 'u-101', 'role': 'engineer'}

@app.post('/tickets', status_code=201)
def create_ticket(payload: TicketIn, user=Depends(get_current_user)):
    return {
        'ticket_id': 't-1',
        'created_by': user['id'],
        'title': payload.title,
        'priority': payload.priority,
    }
